// Supabase Edge Function (Deno). Authoritative game server.
// core.js is generated by `npm run build:edge` from src/server/core.ts (same code the tests run).
// deno-lint-ignore-file no-explicit-any
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4';
import * as core from './core.js';

const url = Deno.env.get('SUPABASE_URL')!;
const service = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const FOUNDER_EMAIL = (Deno.env.get('FOUNDER_EMAIL') ?? '').toLowerCase();
const db = createClient(url, service, { auth: { persistSession: false } });
const cors = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type' };
const json = (b: unknown, status = 200) => new Response(JSON.stringify(b), { status, headers: { ...cors, 'Content-Type': 'application/json' } });
const chatTimes = new Map<string, number[]>(); // per-instance; DB check below is the real limit

// ---------- NPC language model (optional; rule-based replies are the fallback) ----------
const LLM_KEY = Deno.env.get('NPC_LLM_API_KEY') ?? '';
const PROVIDER = (Deno.env.get('NPC_LLM_PROVIDER') ?? 'gemini').toLowerCase(); // 'gemini' | 'openai' (any OpenAI-compatible endpoint: Groq, OpenRouter…)
const MODEL = Deno.env.get('NPC_LLM_MODEL') ?? (PROVIDER === 'gemini' ? 'gemini-3.5-flash-lite' : 'llama-3.1-8b-instant');
const BASE = Deno.env.get('NPC_LLM_BASE_URL') ?? 'https://api.groq.com/openai/v1';
const PER_MIN = Number(Deno.env.get('NPC_LLM_PER_MIN') ?? 12); const PER_DAY = Number(Deno.env.get('NPC_LLM_PER_DAY') ?? 900);
// v1.7 budget: the model is for human players (DMs, Meydan replies) and trials; NPC↔NPC talk stays rule-based,
// with one small batch every 20 min at most (≤15% of the day's budget). Similar questions reuse a cached answer.
const TALK_EVERY_MS = Number(Deno.env.get('NPC_LLM_TALK_EVERY_MS') ?? 20 * 60_000);
const replyCache = new Map<string, { t: number; v: string }>();
const normQ = (s: string): string => s.toLocaleLowerCase('tr').replace(/[^a-zçğıöşü0-9 ]/g, '').replace(/\s+/g, ' ').trim().slice(0, 80);
const minuteCalls: number[] = []; const cache = new Map<string, { t: number; v: string }>(); let backoffUntil = 0;
const today = (): string => new Date().toISOString().slice(0, 10);
async function llm(p: { system: string; user: string }, json = false, maxTokens = 160): Promise<string | null> {
  if (!LLM_KEY) return null;
  const now = Date.now(); if (now < backoffUntil) return null;
  while (minuteCalls.length && now - minuteCalls[0]! > 60_000) minuteCalls.shift();
  if (minuteCalls.length >= PER_MIN) return null;
  const key = `${json}|${p.system.slice(0, 120)}|${p.user}`; const hit = cache.get(key); if (hit && now - hit.t < 600_000) return hit.v;
  minuteCalls.push(now);
  const ctl = new AbortController(); const timer = setTimeout(() => ctl.abort(), 8000);
  try {
    let text = '';
    if (PROVIDER === 'gemini') {
      const r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent`, { method: 'POST', signal: ctl.signal, headers: { 'Content-Type': 'application/json', 'x-goog-api-key': LLM_KEY },
        body: JSON.stringify({ systemInstruction: { parts: [{ text: p.system }] }, contents: [{ role: 'user', parts: [{ text: p.user }] }], generationConfig: { maxOutputTokens: maxTokens, temperature: 0.9, ...(json ? { responseMimeType: 'application/json' } : {}) } }) });
      if (r.status === 429 || r.status >= 500) { backoffUntil = Date.now() + 60_000; return null; }
      if (!r.ok) return null;
      const d = await r.json(); text = (d.candidates?.[0]?.content?.parts ?? []).filter((x: any) => x.text && !x.thought).map((x: any) => x.text).join('').trim();
    } else {
      const r = await fetch(`${BASE}/chat/completions`, { method: 'POST', signal: ctl.signal, headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${LLM_KEY}` },
        body: JSON.stringify({ model: MODEL, max_tokens: maxTokens, temperature: 0.9, messages: [{ role: 'system', content: p.system }, { role: 'user', content: p.user }], ...(json ? { response_format: { type: 'json_object' } } : {}) }) });
      if (r.status === 429 || r.status >= 500) { backoffUntil = Date.now() + 60_000; return null; }
      if (!r.ok) return null;
      const d = await r.json(); text = String(d.choices?.[0]?.message?.content ?? '').trim();
    }
    if (!text) return null;
    if (!json) text = text.replace(/^["“]|["”]$/g, '').replace(/\s+/g, ' ').slice(0, 280);
    cache.set(key, { t: Date.now(), v: text }); if (cache.size > 300) cache.delete(cache.keys().next().value!);
    return text;
  } catch { return null; } finally { clearTimeout(timer); }
}
const parseJson = (s: string | null): any => { if (!s) return null; try { return JSON.parse(s.replace(/^```(json)?|```$/g, '').trim()); } catch { return null; } };
const background = (p: Promise<unknown>): void => { const er = (globalThis as any).EdgeRuntime; if (er?.waitUntil) er.waitUntil(p); else void p; };

async function loadWorld(): Promise<{ state: any; version: number }> {
  const { data } = await db.from('world_state').select('state, version').eq('id', 1).maybeSingle();
  if (data) return { state: core.migrateWorld(data.state), version: data.version };
  const state = core.createWorld(Math.floor(Math.random() * 1e9), Date.now());
  await db.from('world_state').insert({ id: 1, state, version: 0 });
  return { state, version: 0 };
}
/** read → mutate → compare-and-swap commit, retried on conflict */
async function storeNpcChat(msgs: any[]) {
  if (!msgs.length) return;
  await db.from('messages').insert(msgs.map((m) => ({ from_user: null, from_person: m.fromPersonId, from_name: m.fromName, to_person: m.toPersonId, text: String(m.text).slice(0, 280), created_at: new Date(m.at).toISOString() })));
}
async function mutate<T>(f: (w: any) => T, tries = 5): Promise<T> {
  for (let i = 0; i < tries; i++) {
    const { state, version } = await loadWorld();
    const r = f(state);
    const npc = core.drainChat(state);
    const { data: ok } = await db.rpc('commit_world', { new_state: state, expected: version });
    if (ok) { await storeNpcChat(npc); return r; }
    await new Promise((res) => setTimeout(res, (40 + Math.random() * 160) * (1 + Math.min(i, 4) * 0.5))); // v2.0.2: jittered back-off (attack spam starved heartbeats)
  }
  throw new Error('Dünya meşgul, tekrar deneyin.');
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  try {
    const body = await req.json();
    const now = Date.now();
    if (body.op === 'llmtest') { // founder-free health check: does the model answer? (no key is ever returned)
      const r = await llm({ system: 'Kısa cevap ver.', user: 'Bir fırıncı olarak "merhaba" de.' }); return json({ provider: PROVIDER, model: MODEL, configured: !!LLM_KEY, ok: !!r });
    }
    if (body.op === 'candidates') {
      const { data: okAccess } = await db.rpc('check_access', { pw: String(body.access ?? '') });
      if (!okAccess) return json({ error: 'Giriş şifresi yanlış.' });
      const { state } = await loadWorld();
      return json(core.candidates(state));
    }
    if (body.op === 'register') {
      const { data: okAccess } = await db.rpc('check_access', { pw: String(body.access ?? '') });
      if (!okAccess) return json({ error: 'Giriş şifresi yanlış. Davet eden kişiden şifreyi isteyin.' });
      const email = String(body.email ?? '').trim().toLowerCase();
      const { data: created, error } = await db.auth.admin.createUser({ email, password: String(body.password ?? ''), email_confirm: true });
      if (error || !created.user) return json({ error: 'Hesap açılamadı (e-posta kayıtlı ya da şifre çok kısa).' });
      const founder = !!FOUNDER_EMAIL && email === FOUNDER_EMAIL;
      const uid = created.user.id;
      let personId: string;
      try { personId = await mutate((w) => { core.register(w, uid, String(body.name ?? ''), body.prof, founder, now, founder ? null : body.takeOverId ?? null); return w.players[uid].personId; }); }
      catch (e) { await db.auth.admin.deleteUser(uid); return json({ error: String((e as Error).message) }); }
      await db.from('players').insert({ user_id: uid, person_id: personId, display_name: String(body.name ?? '').slice(0, 24), is_founder: founder });
      if (founder) await db.from('game_config').update({ founder_user: uid }).eq('id', 1);
      return json({});
    }
    // authenticated ops
    const token = (req.headers.get('Authorization') ?? '').replace('Bearer ', '');
    const { data: u } = await db.auth.getUser(token);
    if (!u.user) return json({ error: 'oturum yok' }, 401);
    const uid = u.user.id;
    const { data: pl } = await db.from('players').select('*').eq('user_id', uid).maybeSingle();
    if (!pl) return json(null);
    if (pl.banned) return json({ error: 'Sürgün edildiniz.' }, 403);
    switch (body.op) {
      case 'me': return json({ playerId: uid, founder: pl.is_founder });
      case 'heartbeat': {
        let due = false; let batch: { idx: number[]; prompt: { system: string; user: string } } | null = null; let sbatch: unknown = null;
        let out: any;
        try { out = await mutate((w) => {
          const r = core.heartbeat(w, uid, now); due = r.snapshotDue; batch = null;
          if (LLM_KEY && now - (w.llm?.talkAt ?? 0) > TALK_EVERY_MS && core.llmBudget(w, today(), Math.floor(PER_DAY * 0.15))) { const b = core.talkBatch(w, now); if (b) { batch = b; w.llm!.talkAt = now; core.llmSpend(w, today()); } }
          if (LLM_KEY && now - (w.llm?.speechAt ?? 0) > 10 * 60_000 && core.llmBudget(w, today(), Math.floor(PER_DAY * 0.2))) { const b = core.speechBatch(w); if (b) { sbatch = b; w.llm!.speechAt = now; core.llmSpend(w, today()); } }
          return { world: w, summary: r.summary };
        }); } catch { const { state } = await loadWorld(); core.heartbeat(state, uid, now); out = { world: state, summary: null }; batch = null; sbatch = null; due = false; } // v2.0.2: busy world → still answer with a fresh (uncommitted) view so the client never freezes
        const sb = sbatch as { refs: [string, number][]; prompt: { system: string; user: string } } | null;
        if (due) await db.rpc('snapshot_world', { force: false });
        const bt = batch as { idx: number[]; prompt: { system: string; user: string } } | null;
        if (sb) background((async () => { const o = parseJson(await llm(sb.prompt, true, 300)); if (o) await mutate((w) => core.applySpeeches(w, sb.refs, o)); })().catch(() => {}));
        if (bt) background((async () => { const o = parseJson(await llm(bt.prompt, true, 400)); if (o) await mutate((w) => core.applyTalks(w, bt.idx, o, Date.now())); })().catch(() => {}));
        return json(out);
      }
      case 'act': {
        if (body.action?.t === 'defense' && LLM_KEY) {
          let prompt: { system: string; user: string } | null = null;
          const r = await mutate((w) => { const x = core.act(w, uid, body.action, now, true); prompt = x.ok ? core.judgeRequest(w, String(body.action.caseId)) : null; if (prompt) core.llmSpend(w, today()); return x; });
          if (prompt) { const o = parseJson(await llm(prompt, true, 220)); await mutate((w) => core.judgeReply(w, String(body.action.caseId), o, Date.now())); }
          return json(r);
        }
        try { return json(await mutate((w) => core.act(w, uid, body.action, now), 10)); } // v2.0.3: players' actions retry harder and never fail silently
        catch (e) { return json({ ok: false, msg: `Dünya şu an çok meşgul; işleminiz yapılamadı, tekrar deneyin. (${String((e as Error).message ?? e).slice(0, 60)})` }); }
      }
      case 'chat': {
        const since = new Date(now - 30_000).toISOString();
        const { count } = await db.from('messages').select('id', { count: 'exact', head: true }).eq('from_user', uid).gte('created_at', since);
        if ((count ?? 0) >= 5) return json({ error: 'Çok hızlı yazıyorsunuz; biraz bekleyin.' });
        const times = chatTimes.get(uid) ?? []; chatTimes.set(uid, times);
        const to = body.to ? String(body.to) : null;
        let history: { from: string; text: string }[] = [];
        if (to && LLM_KEY) {
          const { data: hist } = await db.from('messages').select('from_name, text, from_person, to_person').or(`and(from_person.eq.${pl.person_id},to_person.eq.${to}),and(from_person.eq.${to},to_person.eq.${pl.person_id})`).order('id', { ascending: false }).limit(6);
          history = (hist ?? []).reverse().map((x: any) => ({ from: x.from_name, text: x.text }));
        }
        let allowed = false;
        const m = await mutate((state) => { const r = core.makeChat(state, uid, String(body.text ?? ''), to, times, now, !!LLM_KEY, history); allowed = false; if (typeof r !== 'string' && r.replies?.length && core.llmBudget(state, today(), PER_DAY)) { allowed = true; core.llmSpend(state, today(), r.replies.length); } return r; });
        if (typeof m === 'string') return json({ error: m });
        await db.from('messages').insert({ from_user: uid, from_person: m.fromPersonId, from_name: m.fromName, to_person: m.toPersonId, text: m.text });
        const out: string[] = [];
        for (const [i, rp] of (m.replies ?? []).entries()) {
          let ai: string | null = null;
          if (allowed && rp.prompt.json) {
            const j = parseJson(await llm(rp.prompt, true, 400));
            if (j?.action && typeof j.action === 'object') {
              const res = await mutate((state) => core.llmOrder(state, uid, rp.npcId, j.action, m.text, Date.now()));
              ai = res ? (res.ok ? j.reply_yes : j.reply_no) || res.reply : (j.reply || null);
            } else ai = typeof j?.reply === 'string' ? j.reply : null;
            if (ai) ai = String(ai).replace(/\s+/g, ' ').slice(0, 280);
          } else if (allowed) {
            const ck = `${rp.npcId}|${normQ(m.text)}|${rp.prompt.user.includes('KABUL') ? 'y' : rp.prompt.user.includes('REDDET') ? 'n' : ''}`; const hit = replyCache.get(ck);
            if (hit && Date.now() - hit.t < 30 * 60_000) ai = hit.v; else { ai = await llm(rp.prompt); if (ai) { replyCache.set(ck, { t: Date.now(), v: ai }); if (replyCache.size > 500) replyCache.delete(replyCache.keys().next().value!); } }
          }
          const text = (rp.to ? '' : `@${m.fromName.split(' ').slice(-1)[0]} `) + (ai ?? rp.fallback.replace(/^@\S+ /, ''));
          out.push(text);
          await db.from('messages').insert({ from_user: null, from_person: rp.npcId, from_name: rp.npcName, to_person: rp.to, text: text.slice(0, 280), created_at: new Date(Date.now() + 500 * (i + 1)).toISOString() });
        }
        return json({ replies: out, ai: allowed && !!LLM_KEY });
      }
      case 'snapshots': {
        if (!pl.is_founder) return json([]);
        const { data } = await db.from('world_snapshots').select('id, created_at, day').order('created_at', { ascending: false });
        return json((data ?? []).map((s: any) => ({ id: String(s.id), at: Date.parse(s.created_at), day: s.day })));
      }
      case 'admin': {
        if (!pl.is_founder) return json({ msg: 'Yetkiniz yok.' }, 403);
        const r = body.req;
        if (r.t === 'setPassword') { if (String(r.password).length < 4) return json({ msg: 'En az 4 karakter.' }); await db.rpc('set_access_password', { pw: String(r.password) }); return json({ msg: 'Giriş şifresi değişti.' }); }
        if (r.t === 'snapshot') { await db.rpc('snapshot_world', { force: true }); return json({ msg: 'Yedek alındı.' }); }
        if (r.t === 'resetWorld') {
          if (r.confirm !== 'SIFIRLA') return json({ msg: 'Onay metni yanlış.' });
          const ok = await db.rpc('snapshot_world', { force: true }); if (ok.error) return json({ msg: 'Yedek alınamadı; sıfırlama iptal.' });
          const ids = await mutate((w) => core.resetWorld(w, now));
          for (const [user_id, person_id] of Object.entries(ids)) await db.from('players').update({ person_id }).eq('user_id', user_id);
          return json({ msg: 'Dünya sıfırlandı (önce yedek alındı).' });
        }
        if (r.t === 'restoreSnapshot') {
          const { data: s } = await db.from('world_snapshots').select('state, day').eq('id', Number(r.id)).maybeSingle();
          if (!s) return json({ msg: 'Yedek yok.' });
          await mutate((w) => { const players = w.players; Object.assign(w, s.state); w.players = { ...w.players, ...players }; w.lastTickAt = now; });
          return json({ msg: `Gün ${s.day} yedeği geri yüklendi.` });
        }
        if (r.t === 'ban') await db.from('players').update({ banned: !!r.banned }).eq('user_id', r.playerId);
        return json({ msg: await mutate((w) => core.admin(w, r)) });
      }
    }
    return json({ error: 'bilinmeyen işlem' }, 400);
  } catch (e) {
    return json({ error: String((e as Error).message ?? e) }, 500);
  }
});
